package com.maahi.iractvremote.core.ir.ac

import com.maahi.iractvremote.model.AcMode
import com.maahi.iractvremote.model.AcState

/**
 * Hitachi Inverter AC HSPE Series Direct Captured IR Commands.
 */
object HitachiBroadlink1091 {

    const val OFF_CMD = ""

    // Pre-captured Cool Mode commands (16Â°C - 30Â°C)
    private val COOL_MAP = mapOf(
        16 to "",
        17 to "",
        18 to "",
        19 to "",
        20 to "",
        21 to "",
        22 to "",
        23 to "",
        24 to "",
        25 to "",
        26 to "",
        27 to "",
        28 to "",
        29 to "",
        30 to "",
    )

    // Pre-captured Heat Mode commands (16Â°C - 30Â°C)
    private val HEAT_MAP = mapOf(
        16 to "",
        17 to "",
        18 to "",
        19 to "",
        20 to "",
        21 to "",
        22 to "",
        23 to "",
        24 to "",
        25 to "",
        26 to "",
        27 to "",
        28 to "",
        29 to "",
        30 to "",
    )

    fun encode(state: AcState): Pair<Int, IntArray> {
        if (!state.power) {
            val pulses = BroadlinkPacketDecoder.decode(OFF_CMD)
            return Pair(BroadlinkPacketDecoder.CARRIER_FREQUENCY_HZ, pulses)
        }

        val clampedTemp = state.temp.coerceIn(16, 30)
        val b64 = when (state.mode) {
            AcMode.HEAT -> HEAT_MAP[clampedTemp] ?: HEAT_MAP[24]!!
            else -> COOL_MAP[clampedTemp] ?: COOL_MAP[24]!!
        }

        val pulses = BroadlinkPacketDecoder.decode(b64)
        return Pair(BroadlinkPacketDecoder.CARRIER_FREQUENCY_HZ, pulses)
    }
}
